Caesar(inputString, shift) {
    ;Asc() changed to Ord() in v2
    ;compare using strCompare instead of operators as they behave differently in v2
    ;returns 0 if equal, negative if char < bound, positive if char > bound
    ;CaseSense := true (or "Case") ensures strict, case-sensitive checking
    out := ""
    Loop Parse inputString
    {
        char := A_LoopField
        isUpper := (StrCompare(char, "A", true) >= 0 && StrCompare(char, "Z", true) <= 0)
        isLower := (StrCompare(char, "a", true) >= 0 && StrCompare(char, "z", true) <= 0)
        if (isUpper)
        {
            out .= Chr(Mod(Ord(char) - Ord("A") + shift, 26) + Ord("A"))
        }
        else if (isLower)
        {
            out .= Chr(Mod(Ord(char) - Ord("a") + shift, 26) + Ord("a"))
        }
        else
        {
            out .= char
        }
    }
    return out
}
