    writeln("Original:  ", txt);
    writeln("Encrypted: ", txt.rot(key));
    writeln("Decrypted: ", txt.rot(key).rot(26 - key));
}

import std.stdio, std.ascii;

void inplaceRot(char[] txt, in int key) pure nothrow {
    foreach (ref c; txt) {
        if (isLower(c))
            c = (c - 'a' + key) % 26 + 'a';
        else if (isUpper(c))
            c = (c - 'A' + key) % 26 + 'A';
    }
}

